jsonb, 'devis', NULL, NULL, 'villes', '["Rabat"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
