INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('8109dc74-58fb-5f14-9a22-e9f595a8f1e0'::uuid, 'ea038ffe-5b9a-52d9-8f1c-c16bdca428d8'::uuid, 'Metal frame — offre clé en main', 'Mission de professionnels BTP portée par DIXI TRAVAUX, basé à Marrakech. Dixi Travaux met à votre service plus de 30 ans d’expertise dans le domaine du bâtiment et de la rénovation. Spécialisée en construction, peinture, plâtrerie, électricité, menuiserie et plomberie, notre entreprise vous garantit des solutions… La mission couvre typiquement les volets réalisation / accompagnement : Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu, Expertise Metal frame, Suivi jusqu''à livraison de la mission. DIXI TRAVAUX intervient à Marrakech, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation metal frame, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Construction Gros Oeuvre', 'https://lechantier.ma/logo.svg', '["https://lechantier.ma/uploads/media/4569aad0b97d.webp", "https://lechantier.ma/uploads/media/66e027146884.webp", "https://lechantier.ma/uploads/media/568c2536f33b.webp", "https://lechantier.ma/uploads/media/db7c5e7ede9e.webp", "https://lechantier.ma/logo.svg"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Metal frame", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Marrakech"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.3.5' LIMIT 1));
