ets", "Copyright © 2025 | Réalisations de Neomedia", "L''excellence technique au service de vos projets", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Entrepreneur"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Tanger"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
