ent"]'::jsonb, '["Voir toutes nos réalisations (94 photos)", "Villas et grands chantiers", "Quelques réalisations récentes", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Fournisseur d''aluminium"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Rabat"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '8.5.4' LIMIT 1));
