ojet ?", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Entreprise de topographie"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '6.2.4' LIMIT 1));
