coustique ?", "Isolation thermique et acoustique pour bâtiments et villas", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Entrepreneur spécialisé dans…"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Rabat"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.2.7' LIMIT 1));
