INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('8eb31ef1-322b-539f-a48d-7c34d90b8ded'::uuid, 'c161a49e-d940-5294-affa-74b51bf3ed2c'::uuid, 'Fournisseur de systèmes de… — offre clé en main', 'Mission de professionnels BTP portée par SAFA CLIM - Installation - Entretien - Location - Froid Industriel - Climatisation Professionnelle - Maroc, basé à Casablanca. Expert Marocain du Froid & Traitement d’Air Entreprise spécialisée dans le froid industriel, la climatisation pro, la ventilation et le traitement d’air.... La mission couvre typiquement les volets fourniture / accompagnement : Page 4, Page 3, Mise en place de systèmes de réfrigération sur mesure, adaptés aux exigences…, Conseil et cadrage de la mission. SAFA CLIM - Installation - Entretien - Location - Froid Industriel - Climatisation Professionnelle - Maroc intervient à Casablanca, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées.', 'Matériaux & équipements', 'http://safaclim.com/wp-content/uploads/2025/11/logo-1.png', '["http://safaclim.com/wp-content/plugins/revslider/sr6/assets/assets/dummy.png", "http://safaclim.com/wp-content/uploads/2025/11/8.png", "http://safaclim.com/wp-content/uploads/2025/11/1.png", "http://safaclim.com/wp-content/uploads/2025/11/2.png", "http://safaclim.com/wp-content/uploads/2025/11/logo-1.png"]'::jsonb, '["Fourniture", "Accompagnement"]'::jsonb, '["Page 4", "Page 3", "Mise en place de systèmes de réfrigération sur mesure, adaptés aux exigences…", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Fournisseur de systèmes de…"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '8.5.3' LIMIT 1));
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('629eb0e4-603e-5c53-8a60-48b86b4016d9'::uuid, 'c464a984-8fc4-529d-9150-84c3b46a28dd'::uuid, 'Topographie, relevés et géomètre-expert', 'Mission de professionnels BTP portée par SMART TOPO - مهندس طبوغرافي محلف - Ingénieur Géomètre Topographe, basé à Casablanca. Topographe à Casablanca : bornage, levés de précision, travaux cadastraux, VRD, expertise foncière, SIG et photogrammétrie par drone. Cabinet d’ingénieur géomètre topographe à Roches Noires. Devis sous 24 h. La mission couvre typiquement les volets étude / accompagnement : Lotissement · Étude complète, Votre projet, Lotissement résidentiel — étude et suivi, Conseil et cadrage de la mission. SMART TOPO - مهندس طبوغرافي محلف - Ingénieur Géomètre Topographe intervient à Casablanca, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation bureau de topographie, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Architecture / Ingénierie', 'https://www.smarttopo.com/assets/img/brand/og.png', '["https://smarttopo.ma/assets/img/photos/hero-accueil.jpg", "https://smarttopo.ma/assets/img/photos/accueil-modele-numerique-de.jpg", "https://smarttopo.ma/assets/img/photos/accueil-plan-topographique-avec.jpg", "https://smarttopo.ma/assets/img/photos/accueil-canevas-geodesique-gnss.jpg", "https://www.smarttopo.com/assets/img/brand/og.png"]'::jsonb, '["Étude", "Accompagnement"]'::jsonb, '["Lotissement · Étude complète", "Votre projet", "Lotissement résidentiel — étude et suivi", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Bureau de topographie"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '6.2.4' LIMIT 1));
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('efec357a-96d8-5b40-a20b-51f6cedbb7c4'::uuid, '80a902f6-d010-5b53-9d5a-fe7f2cdd3819'::uuid, 'Entreprise générale / travaux — réalisation de chantier', 'Mission de professionnels BTP portée par SNCE Société Nouvelle Des Conduites d''Eau, basé à Casablanca. SNCE Société Nouvelle Des Conduites d''Eau est un professionnel BTP basé à Casablanca, spécialisé en Société de travaux publics. Référence citée : Projets →. La mission couvre typiquement les volets réalisation / accompagnement : Projets →, Résidence KAYS Place Rabea Al Adaouia, AGDAL 10090, Rabat, Maroc., Projets réalisés, Conseil et cadrage de la mission. SNCE Société Nouvelle Des Conduites d''Eau intervient à Casablanca, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation société de travaux publics, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Construction Gros Oeuvre', 'http://www.snce.ma/assets/images/logo.webp', '["http://www.snce.ma/assets/images/projets/map/projet-PRJ-2025-SRM-CASA/7.jpeg", "http://www.snce.ma/assets/images/projets/map/projet-PRJ-2024-ORMVAL-MAKH/1.webp", "http://www.snce.ma/assets/images/projets/map/projet-POMP-2024-AMEUR-SALE/1.jpeg", "http://www.snce.ma/assets/images/projets/map/projet-PRJ-2024-ORMVAD-JORF/3.webp", "http://www.snce.ma/assets/images/logo.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Projets →", "Résidence KAYS Place Rabea Al Adaouia, AGDAL 10090, Rabat, Maroc.", "Projets réalisés", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Société de travaux publics"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.4.1' LIMIT 1));
